import { useState } from "react";
import "../styles/Payments.css"

export default function Payments() {
  const [showModal, setShowModal] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState(null);

  const plans = [
    { id: 1, name: "Gói Cơ bản", price: 0, desc: "Dùng miễn phí với giới hạn tính năng" },
    { id: 2, name: "Standard", price: 99000, desc: "Đầy đủ tính năng cơ bản + hỗ trợ thường" },
    { id: 3, name: "Premium", price: 199000, desc: "Toàn bộ tính năng + hỗ trợ cao cấp" },
  ];

  return (
    <div className="payment-container">
      <h2 className="payment-title">Thanh toán & Premium</h2>

      {/* Danh sách gói */}
      <div className="plan-grid">
        {plans.map((plan) => (
          <div key={plan.id} className="plan-card">
            <h3 className="plan-name">{plan.name}</h3>
            <p className="plan-desc">{plan.desc}</p>
            <p className="plan-price">
              {plan.price > 0 ? `${plan.price.toLocaleString()}đ/tháng` : "Miễn phí"}
            </p>
            <button
              className="btn-select"
              onClick={() => {
                setSelectedPlan(plan);
                setShowModal(true);
              }}
            >
              Chọn gói
            </button>
          </div>
        ))}
      </div>

      {/* Modal thanh toán */}
      {showModal && selectedPlan && (
        <div className="modal-overlay">
          <div className="modal">
            <h3 className="modal-title">Thanh toán gói {selectedPlan.name}</h3>
            <p className="modal-price">Giá: {selectedPlan.price.toLocaleString()}đ</p>

            {/* Các trường nhập thông tin */}
            <input className="input" placeholder="Họ và tên" />
            <input className="input" placeholder="Email" />
            <input className="input" placeholder="Số điện thoại" />

            {/* Nút hành động */}
            <div className="modal-actions">
              <button className="btn-cancel" onClick={() => setShowModal(false)}>
                Hủy
              </button>
              <button
                className="btn-pay"
                onClick={() => alert("Fake checkout VNPay")}
              >
                Thanh toán VNPay
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
